import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'casecreation', pathMatch: 'full' },
  { path: 'rolepermission/:id', loadComponent: () => import('../../components/casebuilder/permission/rolepermission/rolepermission.component').then(m => m.RolepermissionComponent) },
  { path: 'userpermission/:id', loadComponent: () => import('../../components/casebuilder/permission/userpermission/userpermission.component').then(m => m.UserpermissionComponent) },
  { path: 'editpermission/:id', loadComponent: () => import('../../components/casebuilder/permission/editpermissions/editpermissions.component').then(m => m.EditpermissionsComponent) }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class PermissionRoutingModule {}
